-- Audio interfaces and streaming mixers in the Mic setup category (docs/PROFILES.md, "Setup parts picker",
-- Joe's decision of October 3, 2026, 5:52 PM ET). Written from general knowledge; not copied from any catalog. No prices or links.
-- kind marks a part as an audio interface; setup entries from the old AUDIO_INTERFACE category show as interfaces too
-- (setup_items.legacy_category, kept by 0011). Re-running the insert is harmless: existing names are only marked as interfaces.
ALTER TABLE parts ADD COLUMN kind text CHECK (kind IN ('AUDIO_INTERFACE'));

ON CONFLICT (category, norm) DO UPDATE SET kind = 'AUDIO_INTERFACE';
